import React, { useState } from 'react';
import { motion, useMotionValue, useTransform, PanInfo, AnimatePresence } from 'framer-motion';
import { ThumbsUp, ThumbsDown, MessageSquare, ArrowUp, Eye } from 'lucide-react';
import { Topic, VoteType } from '../types';
import { useAppStore } from '../store/useAppStore';

interface SwipeCardProps {
  topic: Topic;
  onVote: (vote: VoteType, reason?: string) => void;
  onSkip: () => void;
}

export const SwipeCard: React.FC<SwipeCardProps> = ({ topic, onVote, onSkip }) => {
  const [exitX, setExitX] = useState(0);
  const [exitY, setExitY] = useState(0);

  const x = useMotionValue(0);
  const y = useMotionValue(0);
  const rotate = useTransform(x, [-200, 200], [-25, 25]);
  const opacity = useTransform(x, [-200, -150, 0, 150, 200], [0.5, 1, 1, 1, 0.5]);
  
  // Color overlays
  const bgRed = useTransform(x, [-150, 0], [1, 0]);
  const bgGreen = useTransform(x, [0, 150], [0, 1]);
  const bgGray = useTransform(y, [-150, 0], [1, 0]); // Changed to negative Y (Up)

  const handleDragEnd = (event: any, info: PanInfo) => {
    const threshold = 100;
    const velocityThreshold = 500;

    // Check for diagonal swipes first
    if (info.offset.y > 50) {
      if (info.offset.x > 50) {
        // Right-Down -> Agree
        setExitX(200);
        setExitY(200);
        onVote('agree');
        return;
      } else if (info.offset.x < -50) {
        // Left-Down -> Disagree
        setExitX(-200);
        setExitY(200);
        onVote('disagree');
        return;
      }
    }

    if (info.offset.y < -threshold) { // Changed to negative threshold (Up)
      // Swipe Up -> Skip / Neutral
      setExitY(-200);
      onVote('skip');
    } else if (info.offset.x > threshold || info.velocity.x > velocityThreshold) {
      // Swipe Right -> Agree
      setExitX(200);
      onVote('agree');
    } else if (info.offset.x < -threshold || info.velocity.x < -velocityThreshold) {
      // Swipe Left -> Disagree
      setExitX(-200);
      onVote('disagree');
    }
  };

  return (
    <>
      <motion.div
        style={{ x, y, rotate, opacity }}
        drag
        dragConstraints={{ left: 0, right: 0, top: 0, bottom: 0 }}
        onDragEnd={handleDragEnd}
        className="absolute w-full max-w-sm h-[60vh] bg-white rounded-3xl shadow-xl overflow-hidden cursor-grab active:cursor-grabbing border border-gray-200"
        initial={{ scale: 0.95, opacity: 0 }}
        animate={{ scale: 1, opacity: 1 }}
        exit={{ x: exitX, y: exitY, opacity: 0, transition: { duration: 0.2 } }}
      >
        {/* Overlays */}
        <motion.div style={{ opacity: bgRed }} className="absolute inset-0 bg-red-100/50 z-10 pointer-events-none flex items-center justify-center">
          <ThumbsDown className="w-24 h-24 text-red-500 opacity-50" />
        </motion.div>
        <motion.div style={{ opacity: bgGreen }} className="absolute inset-0 bg-green-100/50 z-10 pointer-events-none flex items-center justify-center">
          <ThumbsUp className="w-24 h-24 text-green-500 opacity-50" />
        </motion.div>
        <motion.div style={{ opacity: bgGray }} className="absolute inset-0 bg-gray-100/50 z-10 pointer-events-none flex items-center justify-center">
          <ArrowUp className="w-24 h-24 text-gray-500 opacity-50" />
        </motion.div>

        {/* Content */}
        <div className="relative z-20 h-full flex flex-col p-6">
          <div className="flex-1 flex flex-col justify-center">
            <span className="text-xs font-bold uppercase tracking-wider text-gray-400 mb-2">{topic.category}</span>
            <h2 className="text-2xl font-bold text-gray-900 mb-4 leading-tight">{topic.question}</h2>
            <p className="text-gray-600 text-sm leading-relaxed">{topic.context}</p>
          </div>
          
          <div className="mt-auto pt-6 border-t border-gray-100 flex justify-between items-center text-gray-400 text-sm">
            <div className="flex items-center gap-1 text-red-500">
              <ThumbsDown className="w-4 h-4" /> {topic.disagreeCount}
            </div>
            
            <button 
              onClick={onSkip}
              className="flex items-center gap-1 px-4 py-2 bg-gray-100 hover:bg-gray-200 rounded-full text-gray-700 font-bold transition-colors"
            >
              <Eye className="w-4 h-4" /> 围观
            </button>

            <div className="flex items-center gap-1 text-green-500">
              <ThumbsUp className="w-4 h-4" /> {topic.agreeCount}
            </div>
          </div>
        </div>
      </motion.div>
    </>
  );
};
