import React, { useState, useEffect } from 'react';
import { useParams, useNavigate } from 'react-router-dom';
import { ArrowLeft, ThumbsUp, ThumbsDown, MessageSquare, Share2, MoreHorizontal, CheckCircle, Sparkles, BrainCircuit, Minus, ChevronDown, Users, Bot, Loader2 } from 'lucide-react';
import { useAppStore } from '../store/useAppStore';
import { motion, AnimatePresence } from 'framer-motion';

export const TopicDetail: React.FC = () => {
  const { id } = useParams<{ id: string }>();
  const navigate = useNavigate();
  const { topics, addComment, voteComment, generateTopicAnalysis, generateCommentAnalysis, currentUser, isAnalyzing } = useAppStore();
  const [newComment, setNewComment] = useState('');
  const [replyingTo, setReplyingTo] = useState<string | null>(null);
  const [replyContent, setReplyContent] = useState('');
  const [expandedAnalysis, setExpandedAnalysis] = useState<Set<string>>(new Set());
  const [showGlobalAnalysis, setShowGlobalAnalysis] = useState(false);
  const [userStance, setUserStance] = useState<'agree' | 'disagree' | 'neutral'>('neutral');
  const [showStanceSelector, setShowStanceSelector] = useState(false);

  const topic = topics.find(t => t.id === id);

  useEffect(() => {
    if (topic) {
      const historyItem = currentUser.history.find(h => h.topicId === topic.id);
      if (historyItem) {
        if (historyItem.vote === 'agree') setUserStance('agree');
        else if (historyItem.vote === 'disagree') setUserStance('disagree');
        else setUserStance('neutral');
      }
    }
  }, [topic, currentUser.history]);

  if (!topic) {
    return <div className="p-8 text-center">未找到话题</div>;
  }

  const totalVotes = topic.agreeCount + topic.disagreeCount + topic.neutralCount;
  const agreePercent = totalVotes > 0 ? Math.round((topic.agreeCount / totalVotes) * 100) : 0;
  const disagreePercent = totalVotes > 0 ? Math.round((topic.disagreeCount / totalVotes) * 100) : 0;
  const neutralPercent = totalVotes > 0 ? 100 - agreePercent - disagreePercent : 100;

  const handleAddComment = (replyToId?: string) => {
    const content = replyToId ? replyContent : newComment;
    if (content.trim()) {
      addComment(topic.id, {
        userId: 'current-user',
        userName: '你',
        userAvatar: 'https://api.dicebear.com/7.x/avataaars/svg?seed=You',
        content: content,
        stance: userStance,
        replyTo: replyToId,
      });
      if (replyToId) {
        setReplyingTo(null);
        setReplyContent('');
      } else {
        setNewComment('');
      }
    }
  };

  const toggleAnalysis = async (commentId: string) => {
    const newSet = new Set(expandedAnalysis);
    if (newSet.has(commentId)) {
      newSet.delete(commentId);
    } else {
      newSet.add(commentId);
      const comment = topic.comments.find(c => c.id === commentId);
      if (comment && !comment.analysis) {
        await generateCommentAnalysis(topic.id, commentId);
      }
    }
    setExpandedAnalysis(newSet);
  };

  const handleGenerateGlobalAnalysis = () => {
    if (!topic.topicAnalysis) {
      generateTopicAnalysis(topic.id);
    }
    setShowGlobalAnalysis(!showGlobalAnalysis);
  };

  return (
    <div className="min-h-screen bg-white pb-20 font-sans">
      {/* Header */}
      <header className="sticky top-0 bg-white/80 backdrop-blur-md z-50 border-b border-gray-100 px-4 h-14 flex items-center justify-between">
        <button onClick={() => navigate(-1)} className="p-2 hover:bg-gray-100 rounded-full">
          <ArrowLeft className="w-5 h-5" />
        </button>
        <h1 className="font-bold text-sm truncate max-w-[200px]">{topic.category}</h1>
        <button className="p-2 hover:bg-gray-100 rounded-full">
          <Share2 className="w-5 h-5" />
        </button>
      </header>

      <main className="max-w-2xl mx-auto p-4">
        {/* Topic Card */}
        <div className="mb-8">
          <h2 className="text-2xl font-bold mb-4 leading-tight">{topic.question}</h2>
          <p className="text-gray-600 mb-6 leading-relaxed">{topic.context}</p>
          
          {/* Visualization */}
          <div className="bg-gray-100 rounded-full h-8 relative overflow-hidden flex mb-2 group cursor-default">
            {agreePercent > 0 && (
              <div 
                className="bg-green-500 h-full flex items-center justify-center transition-all duration-1000 relative"
                style={{ width: `${agreePercent}%` }}
              >
                <span className="text-white font-bold text-xs opacity-0 group-hover:opacity-100 transition-opacity whitespace-nowrap px-1">
                  {agreePercent}% 赞同
                </span>
              </div>
            )}
            {neutralPercent > 0 && (
              <div 
                className="bg-gray-300 h-full flex items-center justify-center transition-all duration-1000 relative"
                style={{ width: `${neutralPercent}%` }}
              >
                <span className="text-white font-bold text-xs opacity-0 group-hover:opacity-100 transition-opacity whitespace-nowrap px-1">
                  {neutralPercent}% 中立
                </span>
              </div>
            )}
            {disagreePercent > 0 && (
              <div 
                className="bg-red-500 h-full flex items-center justify-center transition-all duration-1000 relative"
                style={{ width: `${disagreePercent}%` }}
              >
                <span className="text-white font-bold text-xs opacity-0 group-hover:opacity-100 transition-opacity whitespace-nowrap px-1">
                  {disagreePercent}% 反对
                </span>
              </div>
            )}
          </div>
          <div className="flex justify-between text-xs text-gray-400 px-2">
            <span>{topic.agreeCount} 赞同</span>
            <span>{topic.neutralCount} 中立</span>
            <span>{topic.disagreeCount} 反对</span>
          </div>
        </div>

        {/* Global Analysis Section */}
        <div className="mb-8">
          <button
            onClick={handleGenerateGlobalAnalysis}
            disabled={isAnalyzing}
            className={`w-full bg-gradient-to-r from-indigo-500 to-purple-600 text-white p-3 rounded-xl font-bold flex items-center justify-center gap-2 shadow-lg hover:shadow-xl transition-all ${isAnalyzing ? 'opacity-75 cursor-not-allowed' : ''}`}
          >
            {isAnalyzing ? (
              <>
                <Loader2 className="w-5 h-5 animate-spin" />
                AI 正在辩证思考中...
              </>
            ) : (
              <>
                <BrainCircuit className="w-5 h-5" />
                {showGlobalAnalysis ? '收起 AI 辩证分析' : '生成 AI 辩证分析'}
              </>
            )}
          </button>

          <AnimatePresence>
            {showGlobalAnalysis && topic.topicAnalysis && (
              <motion.div
                initial={{ height: 0, opacity: 0 }}
                animate={{ height: 'auto', opacity: 1 }}
                exit={{ height: 0, opacity: 0 }}
                className="overflow-hidden"
              >
                <div className="mt-4 space-y-4">
                  {/* User Analysis */}
                  <div className="bg-indigo-50 rounded-2xl p-6 border border-indigo-100">
                    <h3 className="font-bold text-indigo-900 mb-2 flex items-center gap-2">
                      <Users className="w-4 h-4" /> 用户观点综述
                    </h3>
                    {topic.topicAnalysis.userAnalysis ? (
                      <>
                        <p className="text-indigo-800 text-sm mb-4 leading-relaxed">{topic.topicAnalysis.userAnalysis.summary}</p>
                        
                        <div className="grid grid-cols-1 md:grid-cols-2 gap-4 mb-4">
                          <div className="bg-white/50 p-3 rounded-lg">
                            <h4 className="font-bold text-green-700 text-xs uppercase mb-2">主要赞同理由</h4>
                            <ul className="list-disc list-inside text-xs text-gray-700 space-y-1">
                              {topic.topicAnalysis.userAnalysis.agreeReasons.map((r, i) => <li key={i}>{r}</li>)}
                            </ul>
                          </div>
                          <div className="bg-white/50 p-3 rounded-lg">
                            <h4 className="font-bold text-red-700 text-xs uppercase mb-2">主要反对理由</h4>
                            <ul className="list-disc list-inside text-xs text-gray-700 space-y-1">
                              {topic.topicAnalysis.userAnalysis.disagreeReasons.map((r, i) => <li key={i}>{r}</li>)}
                            </ul>
                          </div>
                        </div>

                        <div className="flex justify-between items-center text-xs text-indigo-400 border-t border-indigo-100 pt-3">
                          <span>论证强度: {topic.topicAnalysis.userAnalysis.overallStrength}</span>
                        </div>
                      </>
                    ) : (
                      <p className="text-indigo-400 text-sm italic">暂无用户评论，AI 无法进行归纳。</p>
                    )}
                  </div>

                  {/* AI Perspective */}
                  <div className="bg-purple-50 rounded-2xl p-6 border border-purple-100">
                    <h3 className="font-bold text-purple-900 mb-2 flex items-center gap-2">
                      <Bot className="w-4 h-4" /> AI 辩证视角
                    </h3>
                    <p className="text-purple-800 text-sm mb-4 leading-relaxed">{topic.topicAnalysis.aiPerspective.summary}</p>
                    <ul className="list-disc list-inside text-xs text-purple-700 space-y-1">
                      {topic.topicAnalysis.aiPerspective.points.map((p, i) => (
                        <li key={i}>
                          {typeof p === 'string' ? p : (p as any).content || (p as any).title || JSON.stringify(p)}
                        </li>
                      ))}
                    </ul>
                  </div>
                </div>
              </motion.div>
            )}
          </AnimatePresence>
        </div>

        {/* Comments Section */}
        <div className="space-y-6">
          <h3 className="font-bold text-lg flex items-center gap-2">
            讨论 <span className="text-gray-400 text-sm font-normal">({topic.comments.length})</span>
          </h3>

          {topic.comments.map((comment) => (
            <div key={comment.id} className={`border-b border-gray-100 pb-6 last:border-0 ${comment.replyTo ? 'pl-8 border-l-2 border-l-gray-100' : ''}`}>
              <div className="flex items-start gap-3 mb-3">
                <img 
                  src={comment.userAvatar} 
                  alt={comment.userName} 
                  className="w-10 h-10 rounded-full bg-gray-200 cursor-pointer hover:opacity-80 transition-opacity" 
                  onClick={() => navigate(`/user/${comment.userId}`)}
                />
                <div className="flex-1">
                  <div className="flex justify-between items-start">
                    <div>
                      <h4 
                        className="font-bold text-sm cursor-pointer hover:text-blue-600 transition-colors"
                        onClick={() => navigate(`/user/${comment.userId}`)}
                      >
                        {comment.userName}
                      </h4>
                      <span className="text-xs text-gray-400">{new Date(comment.createdAt).toLocaleDateString()}</span>
                    </div>
                    <div className={`text-xs px-2 py-0.5 rounded-full font-bold ${
                      comment.stance === 'agree' ? 'bg-green-100 text-green-700' :
                      comment.stance === 'disagree' ? 'bg-red-100 text-red-700' :
                      'bg-gray-100 text-gray-700'
                    }`}>
                      {comment.stance === 'agree' ? '赞同' : comment.stance === 'disagree' ? '反对' : '中立'}
                    </div>
                  </div>
                </div>
              </div>

              <p className="text-gray-800 text-sm leading-relaxed mb-3">
                {comment.replyTo && <span className="text-gray-400 mr-1">回复 @...</span>}
                {comment.content}
              </p>

              {/* AI Analysis Card (Collapsible) */}
              <AnimatePresence>
                {expandedAnalysis.has(comment.id) && comment.analysis && (
                  <motion.div
                    initial={{ height: 0, opacity: 0 }}
                    animate={{ height: 'auto', opacity: 1 }}
                    exit={{ height: 0, opacity: 0 }}
                    className="overflow-hidden mb-3"
                  >
                    <div className="bg-blue-50 rounded-lg p-3 text-xs border border-blue-100">
                      <div className="flex items-center gap-2 mb-2 text-blue-700 font-bold uppercase tracking-wider">
                        <CheckCircle className="w-3 h-3" /> AI 单条分析
                      </div>
                      <div className="grid grid-cols-2 gap-2">
                        <div>
                          <span className="text-blue-400 block mb-1">核心论点</span>
                          <span className="text-blue-900 font-medium">{comment.analysis.argument}</span>
                        </div>
                        <div>
                          <span className="text-blue-400 block mb-1">论据</span>
                          <span className="text-blue-900 font-medium">{comment.analysis.evidence}</span>
                        </div>
                        <div>
                          <span className="text-blue-400 block mb-1">论证方式</span>
                          <span className="text-blue-900 font-medium">{comment.analysis.method}</span>
                        </div>
                        <div>
                          <span className="text-blue-400 block mb-1">论证强度</span>
                          <span className={`font-bold px-2 py-0.5 rounded-full inline-block ${
                            comment.analysis.strength === 'high' ? 'bg-green-100 text-green-700' :
                            comment.analysis.strength === 'medium' ? 'bg-yellow-100 text-yellow-700' :
                            'bg-red-100 text-red-700'
                          }`}>
                            {comment.analysis.strength.toUpperCase()}
                          </span>
                        </div>
                      </div>
                    </div>
                  </motion.div>
                )}
              </AnimatePresence>

              <div className="flex items-center gap-4 text-gray-400 text-sm">
                <button 
                  onClick={() => voteComment(topic.id, comment.id, 'like')}
                  className={`flex items-center gap-1 transition-colors ${comment.userVote === 'like' ? 'text-green-500 font-bold' : 'hover:text-green-500'}`}
                >
                  <ThumbsUp className={`w-4 h-4 ${comment.userVote === 'like' ? 'fill-current' : ''}`} /> {comment.likes}
                </button>
                <button 
                  onClick={() => voteComment(topic.id, comment.id, 'dislike')}
                  className={`flex items-center gap-1 transition-colors ${comment.userVote === 'dislike' ? 'text-red-500 font-bold' : 'hover:text-red-500'}`}
                >
                  <ThumbsDown className={`w-4 h-4 ${comment.userVote === 'dislike' ? 'fill-current' : ''}`} /> {comment.dislikes}
                </button>
                <button 
                  onClick={() => setReplyingTo(replyingTo === comment.id ? null : comment.id)}
                  className={`flex items-center gap-1 transition-colors ${replyingTo === comment.id ? 'text-black' : 'hover:text-blue-500'}`}
                >
                  <MessageSquare className="w-4 h-4" /> 回复
                </button>
                <button 
                  onClick={() => toggleAnalysis(comment.id)}
                  className={`flex items-center gap-1 transition-colors ${expandedAnalysis.has(comment.id) ? 'text-blue-600' : 'hover:text-blue-600'}`}
                >
                  <Sparkles className="w-4 h-4" /> AI 分析
                </button>
              </div>

              {/* Reply Input */}
              <AnimatePresence>
                {replyingTo === comment.id && (
                  <motion.div
                    initial={{ height: 0, opacity: 0 }}
                    animate={{ height: 'auto', opacity: 1 }}
                    exit={{ height: 0, opacity: 0 }}
                    className="overflow-hidden mt-3"
                  >
                    <div className="flex gap-2">
                      <input
                        type="text"
                        value={replyContent}
                        onChange={(e) => setReplyContent(e.target.value)}
                        placeholder={`回复 ${comment.userName}...`}
                        className="flex-1 bg-gray-50 rounded-full px-4 py-2 text-sm border border-gray-200 focus:ring-1 focus:ring-black outline-none"
                        onKeyDown={(e) => e.key === 'Enter' && handleAddComment(comment.id)}
                        autoFocus
                      />
                      <button 
                        onClick={() => handleAddComment(comment.id)}
                        disabled={!replyContent.trim()}
                        className="bg-black text-white rounded-full px-4 py-2 text-xs font-bold disabled:opacity-50"
                      >
                        发送
                      </button>
                    </div>
                  </motion.div>
                )}
              </AnimatePresence>
            </div>
          ))}
        </div>
      </main>

      {/* Main Comment Input */}
      <div className="fixed bottom-0 left-0 right-0 bg-white border-t border-gray-100 p-4 pb-8">
        <div className="max-w-2xl mx-auto flex items-center gap-2">
          <div className="flex-1 bg-gray-100 rounded-full px-4 py-2 flex items-center gap-2 focus-within:ring-2 focus-within:ring-black focus-within:bg-white transition-all">
            <input
              type="text"
              value={newComment}
              onChange={(e) => setNewComment(e.target.value)}
              placeholder="加入讨论..."
              className="flex-1 bg-transparent outline-none text-sm"
              onKeyDown={(e) => e.key === 'Enter' && handleAddComment()}
            />
          </div>
          
          {/* Stance Selector */}
          <div className="relative">
            <button
              onClick={() => setShowStanceSelector(!showStanceSelector)}
              className={`flex items-center gap-1 px-3 py-2 rounded-full text-xs font-bold transition-colors ${
                userStance === 'agree' ? 'bg-green-100 text-green-700' :
                userStance === 'disagree' ? 'bg-red-100 text-red-700' :
                'bg-gray-100 text-gray-700'
              }`}
            >
              {userStance === 'agree' ? '赞同' : userStance === 'disagree' ? '反对' : '中立'}
              <ChevronDown className="w-3 h-3" />
            </button>
            
            <AnimatePresence>
              {showStanceSelector && (
                <motion.div
                  initial={{ opacity: 0, y: 10 }}
                  animate={{ opacity: 1, y: 0 }}
                  exit={{ opacity: 0, y: 10 }}
                  className="absolute bottom-full right-0 mb-2 bg-white rounded-xl shadow-xl border border-gray-100 p-1 flex flex-col gap-1 min-w-[80px]"
                >
                  <button
                    onClick={() => { setUserStance('agree'); setShowStanceSelector(false); }}
                    className="px-3 py-2 rounded-lg text-xs font-bold text-left hover:bg-green-50 text-green-700"
                  >
                    赞同
                  </button>
                  <button
                    onClick={() => { setUserStance('neutral'); setShowStanceSelector(false); }}
                    className="px-3 py-2 rounded-lg text-xs font-bold text-left hover:bg-gray-50 text-gray-700"
                  >
                    中立
                  </button>
                  <button
                    onClick={() => { setUserStance('disagree'); setShowStanceSelector(false); }}
                    className="px-3 py-2 rounded-lg text-xs font-bold text-left hover:bg-red-50 text-red-700"
                  >
                    反对
                  </button>
                </motion.div>
              )}
            </AnimatePresence>
          </div>

          <button 
            onClick={() => handleAddComment()}
            disabled={!newComment.trim()}
            className="bg-black text-white rounded-full px-4 py-2 text-sm font-bold disabled:opacity-50 disabled:cursor-not-allowed hover:bg-gray-800 transition-colors"
          >
            发布
          </button>
        </div>
      </div>
    </div>
  );
};
