import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import { ArrowLeft, Clock, ThumbsUp, ThumbsDown, Minus, Settings, Key, Cpu, Globe, CheckCircle, AlertCircle, Box, Info, RefreshCw, LogOut } from 'lucide-react';
import { useAppStore } from '../store/useAppStore';
import { AISettings } from '../types';

export const Profile: React.FC = () => {
  const navigate = useNavigate();
  const { currentUser, topics, aiSettings, setAISettings, verifyAIConfig, fetchModels, signOut, setLoginModalOpen } = useAppStore();
  const [apiKey, setApiKey] = useState(aiSettings.apiKey);
  const [provider, setProvider] = useState<AISettings['provider']>(aiSettings.provider);
  const [baseUrl, setBaseUrl] = useState(aiSettings.baseUrl || '');
  const [model, setModel] = useState(aiSettings.model || '');
  const [isEditing, setIsEditing] = useState(false);
  const [verificationStatus, setVerificationStatus] = useState<'idle' | 'loading' | 'success' | 'error'>('idle');
  const [errorMessage, setErrorMessage] = useState('');
  const [availableModels, setAvailableModels] = useState<string[]>(aiSettings.availableModels || []);
  const [isLoadingModels, setIsLoadingModels] = useState(false);

  const getTopicQuestion = (id: string) => {
    return topics.find(t => t.id === id)?.question || '未知话题';
  };

  const handleSaveSettings = () => {
    setAISettings({ provider, apiKey, baseUrl, model, availableModels });
    setIsEditing(false);
    setVerificationStatus('idle');
    setErrorMessage('');
  };

  const handleVerify = async () => {
    setVerificationStatus('loading');
    setErrorMessage('');
    // Update store temporarily to verify
    setAISettings({ provider, apiKey, baseUrl, model });
    try {
      const success = await verifyAIConfig();
      if (success) {
        setVerificationStatus('success');
        // Fetch models after successful verification
        setIsLoadingModels(true);
        const models = await fetchModels();
        setAvailableModels(models);
        setIsLoadingModels(false);
        if (models.length > 0 && !models.includes(model)) {
          setModel(models[0]); // Auto-select first model if current is invalid
        }
      } else {
        setVerificationStatus('error');
      }
    } catch (error: any) {
      setVerificationStatus('error');
      setErrorMessage(error.message || '验证失败');
    }
  };

  return (
    <div className="min-h-screen bg-gray-50 pb-20">
      <header className="bg-white border-b border-gray-100 px-4 h-14 flex items-center gap-4 sticky top-0 z-10">
        <button onClick={() => navigate(-1)} className="p-2 hover:bg-gray-100 rounded-full">
          <ArrowLeft className="w-5 h-5" />
        </button>
        <h1 className="font-bold text-lg">个人主页</h1>
      </header>

      <main className="max-w-md mx-auto p-4 space-y-6">
        {/* User Info */}
        <div className="bg-white rounded-2xl p-6 shadow-sm text-center">
          <img 
            src={currentUser.avatar} 
            alt={currentUser.name} 
            className="w-24 h-24 rounded-full mx-auto mb-4 bg-gray-200"
          />
          <h2 className="text-xl font-bold">{currentUser.name}</h2>
          <p className="text-gray-500 text-sm">{currentUser.bio}</p>
        </div>

        {/* AI Settings */}
        <div className="bg-white rounded-2xl p-6 shadow-sm">
          <div className="flex items-center justify-between mb-4">
            <h3 className="font-bold text-lg flex items-center gap-2">
              <Settings className="w-5 h-5" /> AI 设置
            </h3>
            {!isEditing ? (
              <button 
                onClick={() => setIsEditing(true)}
                className="text-sm text-blue-600 font-medium"
              >
                编辑
              </button>
            ) : (
              <button 
                onClick={handleSaveSettings}
                className="text-sm text-green-600 font-medium"
              >
                保存
              </button>
            )}
          </div>

          <div className="space-y-4">
            <div className="bg-blue-50 p-3 rounded-lg flex items-start gap-2 text-xs text-blue-700">
              <Info className="w-4 h-4 flex-shrink-0 mt-0.5" />
              <p>
                注意：浏览器直接调用 API 可能会因 CORS 策略被拦截。
                如果验证失败，请尝试使用支持 CORS 的代理地址，或者忽略错误强制保存（如果确定配置正确）。
              </p>
            </div>

            <div>
              <label className="block text-sm font-medium text-gray-700 mb-1 flex items-center gap-1">
                <Cpu className="w-4 h-4" /> 模型供应商
              </label>
              <select
                value={provider}
                onChange={(e) => setProvider(e.target.value as any)}
                disabled={!isEditing}
                className="w-full p-2 bg-gray-50 rounded-lg border border-gray-200 text-sm outline-none focus:ring-2 focus:ring-black disabled:opacity-50"
              >
                <option value="deepseek">DeepSeek</option>
                <option value="openai">OpenAI</option>
                <option value="anthropic">Anthropic</option>
                <option value="custom">自定义 (OpenAI 兼容)</option>
              </select>
            </div>

            {provider === 'custom' && (
              <div>
                <label className="block text-sm font-medium text-gray-700 mb-1 flex items-center gap-1">
                  <Globe className="w-4 h-4" /> Base URL
                </label>
                <input
                  type="text"
                  value={baseUrl}
                  onChange={(e) => setBaseUrl(e.target.value)}
                  disabled={!isEditing}
                  placeholder="https://api.example.com/v1"
                  className="w-full p-2 bg-gray-50 rounded-lg border border-gray-200 text-sm outline-none focus:ring-2 focus:ring-black disabled:opacity-50"
                />
              </div>
            )}

            <div>
              <label className="block text-sm font-medium text-gray-700 mb-1 flex items-center gap-1">
                <Key className="w-4 h-4" /> API Key
              </label>
              <input
                type="password"
                value={apiKey}
                onChange={(e) => setApiKey(e.target.value)}
                disabled={!isEditing}
                placeholder="sk-..."
                className="w-full p-2 bg-gray-50 rounded-lg border border-gray-200 text-sm outline-none focus:ring-2 focus:ring-black disabled:opacity-50"
              />
            </div>

            <div>
              <label className="block text-sm font-medium text-gray-700 mb-1 flex items-center gap-1">
                <Box className="w-4 h-4" /> 模型名称
              </label>
              {availableModels.length > 0 && isEditing ? (
                <div className="relative">
                  <select
                    value={model}
                    onChange={(e) => setModel(e.target.value)}
                    disabled={!isEditing || isLoadingModels}
                    className="w-full p-2 bg-gray-50 rounded-lg border border-gray-200 text-sm outline-none focus:ring-2 focus:ring-black disabled:opacity-50 appearance-none"
                  >
                    {availableModels.map(m => (
                      <option key={m} value={m}>{m}</option>
                    ))}
                  </select>
                  {isLoadingModels && (
                    <div className="absolute right-2 top-2">
                      <RefreshCw className="w-4 h-4 animate-spin text-gray-400" />
                    </div>
                  )}
                </div>
              ) : (
                <input
                  type="text"
                  value={model}
                  onChange={(e) => setModel(e.target.value)}
                  disabled={!isEditing}
                  placeholder={provider === 'deepseek' ? 'deepseek-chat' : 'gpt-4o'}
                  className="w-full p-2 bg-gray-50 rounded-lg border border-gray-200 text-sm outline-none focus:ring-2 focus:ring-black disabled:opacity-50"
                />
              )}
              {isEditing && availableModels.length === 0 && (
                <p className="text-xs text-gray-400 mt-1">验证成功后可选择模型</p>
              )}
            </div>

            {isEditing && (
              <div className="pt-2 space-y-2">
                <button
                  onClick={handleVerify}
                  disabled={verificationStatus === 'loading' || !apiKey}
                  className={`w-full py-2 rounded-lg text-sm font-medium flex items-center justify-center gap-2 transition-colors ${
                    verificationStatus === 'success' ? 'bg-green-100 text-green-700' :
                    verificationStatus === 'error' ? 'bg-red-100 text-red-700' :
                    'bg-gray-100 text-gray-700 hover:bg-gray-200'
                  }`}
                >
                  {verificationStatus === 'loading' && '验证中...'}
                  {verificationStatus === 'success' && <><CheckCircle className="w-4 h-4" /> 验证成功</>}
                  {verificationStatus === 'error' && <><AlertCircle className="w-4 h-4" /> 验证失败</>}
                  {verificationStatus === 'idle' && '验证配置并获取模型'}
                </button>
                
                {verificationStatus === 'error' && (
                  <div className="text-xs text-red-600 bg-red-50 p-2 rounded">
                    错误信息: {errorMessage}
                  </div>
                )}
              </div>
            )}
          </div>
        </div>

        {/* History */}
        <div>
          <h3 className="font-bold text-lg mb-4 flex items-center gap-2">
            <Clock className="w-5 h-5" /> 历史记录
          </h3>

          <div className="space-y-3">
            {currentUser.history.length === 0 ? (
              <p className="text-gray-400 text-center py-8">暂无历史记录。快去滑动表态吧！</p>
            ) : (
              currentUser.history.map((item, index) => (
                <div 
                  key={index}
                  onClick={() => navigate(`/topic/${item.topicId}`)}
                  className="bg-white p-4 rounded-xl shadow-sm border border-gray-100 cursor-pointer hover:border-black transition-colors"
                >
                  <div className="flex items-start justify-between mb-2">
                    <span className={`text-xs font-bold px-2 py-1 rounded-full flex items-center gap-1 ${
                      item.vote === 'agree' ? 'bg-green-100 text-green-700' :
                      item.vote === 'disagree' ? 'bg-red-100 text-red-700' :
                      'bg-gray-100 text-gray-700'
                    }`}>
                      {item.vote === 'agree' && <ThumbsUp className="w-3 h-3" />}
                      {item.vote === 'disagree' && <ThumbsDown className="w-3 h-3" />}
                      {item.vote === 'skip' && <Minus className="w-3 h-3" />}
                      {item.vote === 'agree' ? '赞同' : item.vote === 'disagree' ? '反对' : '跳过'}
                    </span>
                    <span className="text-xs text-gray-400">
                      {new Date(item.timestamp).toLocaleDateString()}
                    </span>
                  </div>
                  <h4 className="font-medium text-sm line-clamp-2 mb-1">
                    {getTopicQuestion(item.topicId)}
                  </h4>
                  {item.reason && (
                    <p className="text-xs text-gray-500 italic">"{item.reason}"</p>
                  )}
                </div>
              ))
            )}
          </div>
        </div>

        {/* Logout */}
        <div className="pt-4">
          <button
            onClick={async () => {
              await signOut();
              setLoginModalOpen(true);
            }}
            className="w-full bg-white text-red-600 p-4 rounded-2xl font-bold flex items-center justify-center gap-2 shadow-sm hover:bg-red-50 transition-all"
          >
            <LogOut className="w-5 h-5" />
            退出登录 / 切换账号
          </button>
        </div>
      </main>
    </div>
  );
};
