import React from 'react';
import { Search, User, Plus, Menu } from 'lucide-react';
import { useAppStore } from '../store/useAppStore';

const CATEGORIES = ['全部', '社会', '情感', '科技', '哲学', '职场', '教育', '体育', '娱乐', '历史', '商业', '心理'];

import { useNavigate } from 'react-router-dom';

export const Header: React.FC = () => {
  const { activeCategory, setCategory, searchQuery, setSearchQuery, toggleCreateModal } = useAppStore();
  const navigate = useNavigate();

  return (
    <header className="fixed top-0 left-0 right-0 bg-white/80 backdrop-blur-md z-50 border-b border-gray-100 h-16">
      <div className="max-w-md mx-auto h-full flex items-center justify-between px-4 gap-4">
        <div className="flex-1 flex items-center gap-2 overflow-x-auto no-scrollbar min-w-0 mask-linear-fade">
          {CATEGORIES.map((cat) => (
            <button
              key={cat}
              onClick={() => setCategory(cat)}
              className={`px-3 py-1 rounded-full text-sm whitespace-nowrap transition-colors flex-shrink-0 ${
                activeCategory === cat
                  ? 'bg-black text-white'
                  : 'bg-gray-100 text-gray-600 hover:bg-gray-200'
              }`}
            >
              {cat}
            </button>
          ))}
        </div>

        <div className="flex items-center gap-2 flex-shrink-0">
          <div className="relative hidden sm:block">
            <input
              type="text"
              placeholder="搜索..."
              value={searchQuery}
              onChange={(e) => setSearchQuery(e.target.value)}
              className="pl-8 pr-3 py-1 bg-gray-100 rounded-full text-sm w-24 focus:w-40 transition-all outline-none"
            />
            <Search className="w-4 h-4 absolute left-2.5 top-1.5 text-gray-400" />
          </div>
          
          <button 
            onClick={() => toggleCreateModal(true)}
            className="p-2 hover:bg-gray-100 rounded-full"
          >
            <Plus className="w-5 h-5 text-gray-700" />
          </button>
          
          <button 
            onClick={() => navigate('/profile')}
            className="p-2 hover:bg-gray-100 rounded-full"
          >
            <User className="w-5 h-5 text-gray-700" />
          </button>
        </div>
      </div>
    </header>
  );
};
