const DEFAULT_AI_CONFIG: AISettings = {
  provider: (window.ENV?.AI_PROVIDER || import.meta.env.VITE_AI_PROVIDER as any) || 'deepseek',
  apiKey: window.ENV?.AI_API_KEY || import.meta.env.VITE_AI_API_KEY || '',
  baseUrl: window.ENV?.AI_BASE_URL || import.meta.env.VITE_AI_BASE_URL || 'https://api.deepseek.com/v1',
  model: window.ENV?.AI_MODEL || import.meta.env.VITE_AI_MODEL || 'deepseek-chat'
};

const callLLM = async (settings: AISettings, prompt: string) => {
  // Fallback to mock if no API key
  if (!settings.apiKey) return null;

  let baseUrl = settings.baseUrl || (settings.provider === 'openai' ? 'https://api.openai.com/v1' : 'https://api.deepseek.com/v1');
  // Remove trailing slash if present
  baseUrl = baseUrl.replace(/\/$/, '');

  const model = settings.model || (settings.provider === 'openai' ? 'gpt-3.5-turbo' : 'deepseek-chat');
  
  try {
    const response = await fetch(`${baseUrl}/chat/completions`, {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'Authorization': `Bearer ${settings.apiKey}`
      },
      body: JSON.stringify({
        model: model,
        messages: [{ role: 'user', content: prompt }],
        temperature: 0.7
      })
    });
    
    if (!response.ok) {
      const errorData = await response.json().catch(() => ({}));
      throw new Error(errorData.error?.message || `API call failed: ${response.status} ${response.statusText}`);
    }
    const data = await response.json();
    return data.choices[0].message.content;
  } catch (error: any) {
    console.error('LLM Error:', error);
    throw error;
  }
};

