export const useAppStore = create<AppState>((set, get) => ({
  currentUser: MOCK_USERS[0],
  users: MOCK_USERS,
  topics: [],
  currentTopicIndex: 0,
  activeCategory: '全部',
  searchQuery: '',
  isCreateModalOpen: false,
  isAnalyzing: false,
  isLoginModalOpen: false,
  session: null,
  aiSettings: DEFAULT_AI_CONFIG,

  setSession: (session) => set({ session }),
  setLoginModalOpen: (isOpen) => set({ isLoginModalOpen: isOpen }),

  checkAuth: async () => {
    try {
      const { data: { session } } = await supabase.auth.getSession();
      set({ session });

      const loadUserData = async (userId: string) => {
        const { data: history } = await supabase
          .from('user_history')
          .select('*')
          .eq('user_id', userId);
          
        set(state => ({
          currentUser: {
            ...state.currentUser,
            id: userId,
            name: session?.user.user_metadata.name || session?.user.email?.split('@')[0] || 'User',
            avatar: session?.user.user_metadata.avatar_url || state.currentUser.avatar,
            history: history?.map((h: any) => ({
              topicId: h.topic_id,
              vote: h.vote,
              reason: h.reason,
              timestamp: h.created_at
            })) || []
          }
        }));
      };

      if (session) {
        await loadUserData(session.user.id);
      }

      supabase.auth.onAuthStateChange(async (_event, session) => {
        set({ session });
        if (session) {
          await loadUserData(session.user.id);
        } else {
          set(state => ({
            currentUser: { ...MOCK_USERS[0], history: [] }
          }));
        }
      });
    } catch (error) {
      console.warn('Supabase auth check failed:', error);
    }
  },

  fetchTopics: async () => {
    const { session } = get();
    try {
      const { data: topics, error } = await supabase
        .from('topics')
        .select(`
          *,
          comments (
            *,
            profiles (username, avatar_url)
          )
        `)
        .order('created_at', { ascending: false });
        
      if (error) throw error;

      let userVotes: any[] = [];
      if (session) {
        const { data: votes } = await supabase
          .from('comment_votes')
          .select('*')
          .eq('user_id', session.user.id);
        userVotes = votes || [];
      }

      if (topics && topics.length > 0) {
        const mappedTopics = topics.map((t: any) => ({
          ...t,
          authorId: t.author_id,
          agreeCount: t.agree_count,
          disagreeCount: t.disagree_count,
          neutralCount: t.neutral_count,
          comments: t.comments.map((c: any) => {
            const vote = userVotes.find(v => v.comment_id === c.id);
            return {
              ...c,
              userId: c.user_id,
              userName: c.profiles?.username || 'User',
              userAvatar: c.profiles?.avatar_url || '',
              replyTo: c.reply_to,
              userVote: vote ? vote.vote_type : undefined
            };
          })
        }));
        set({ topics: mappedTopics });
      }
    } catch (error) {
      console.warn('Error fetching topics:', error);
    }
  },

  signOut: async () => {
    await supabase.auth.signOut();
    set({ 
      session: null, 
      currentUser: { ...MOCK_USERS[0], history: [] } 
    });
  },

  setCategory: (category) => set({ activeCategory: category, currentTopicIndex: 0 }),
  setSearchQuery: (query) => set({ searchQuery: query }),
  toggleCreateModal: (isOpen) => set({ isCreateModalOpen: isOpen }),
  setAISettings: (settings) => set({ aiSettings: settings }),

  swipeTopic: async (topicId, vote, reason) => {
    const { session, setLoginModalOpen } = get();
    if (!session) {
      setLoginModalOpen(true);
      return;
    }

    try {
      await supabase.from('user_history').insert({
        user_id: session.user.id,
        topic_id: topicId,
        vote,
        reason
      });

      // Update topic counts
      const topic = get().topics.find(t => t.id === topicId);
      if (topic) {
        const updateData: any = {};
        if (vote === 'agree') updateData.agree_count = topic.agreeCount + 1;
        if (vote === 'disagree') updateData.disagree_count = topic.disagreeCount + 1;
        if (vote === 'skip') updateData.neutral_count = topic.neutralCount + 1;
        
        await supabase.from('topics').update(updateData).eq('id', topicId);
      }
    } catch (error) {
      console.error('Failed to save vote to Supabase:', error);
    }

    set((state) => {
    const newHistory = [
      ...state.currentUser.history,
      {
        topicId,
        vote,
        reason,
        timestamp: new Date().toISOString()
      }
    ];
    
    // Update topic counts
    const newTopics = state.topics.map(t => {
      if (t.id === topicId) {
        return {
          ...t,
          agreeCount: vote === 'agree' ? t.agreeCount + 1 : t.agreeCount,
          disagreeCount: vote === 'disagree' ? t.disagreeCount + 1 : t.disagreeCount,
          neutralCount: vote === 'skip' ? t.neutralCount + 1 : t.neutralCount
        };
      }
      return t;
    });

    return {
      currentUser: { ...state.currentUser, history: newHistory },
      topics: newTopics,
      currentTopicIndex: state.currentTopicIndex + 1
    };
  });
  },

  addTopic: async (topicData) => {
    const { session } = get();
    if (!session) return;

    try {
      const { data, error } = await supabase
        .from('topics')
        .insert({
          category: topicData.category,
          question: topicData.question,
          context: topicData.context,
          tags: topicData.tags,
          author_id: session.user.id
        })
        .select()
        .single();

      if (error) throw error;

      const newTopic = {
        ...data,
        authorId: data.author_id,
        agreeCount: data.agree_count,
        disagreeCount: data.disagree_count,
        neutralCount: data.neutral_count,
        comments: []
      };

      set((state) => ({
        topics: [newTopic, ...state.topics],
        isCreateModalOpen: false
      }));
    } catch (error) {
      console.error('Error adding topic:', error);
    }
  },

  addComment: async (topicId, commentData) => {
    const { session, setLoginModalOpen } = get();
    if (!session) {
      setLoginModalOpen(true);
      return;
    }

    try {
      const { data, error } = await supabase
        .from('comments')
        .insert({
          topic_id: topicId,
          user_id: session.user.id,
          content: commentData.content,
          stance: commentData.stance,
          reply_to: commentData.replyTo
        })
        .select()
        .single();

      if (error) throw error;

      const newComment = {
        ...data,
        userId: data.user_id,
        userName: session.user.user_metadata.name || 'You',
        userAvatar: session.user.user_metadata.avatar_url || '',
        replyTo: data.reply_to,
        likes: 0,
        dislikes: 0
      };

      set((state) => ({
        topics: state.topics.map(t => {
          if (t.id === topicId) {
            return {
              ...t,
              comments: [...t.comments, newComment]
            };
          }
          return t;
        })
      }));
    } catch (error) {
      console.error('Error adding comment:', error);
    }
  },

  voteComment: async (topicId, commentId, type) => {
    const { session, setLoginModalOpen } = get();
    if (!session) {
      setLoginModalOpen(true);
      return;
    }

    set((state) => ({
      topics: state.topics.map(t => {
        if (t.id === topicId) {
          return {
            ...t,
            comments: t.comments.map(c => {
              if (c.id === commentId) {
                let newLikes = c.likes;
                let newDislikes = c.dislikes;
                let newUserVote = c.userVote;

                if (type === 'like') {
                  if (c.userVote === 'like') {
                    newLikes--;
                    newUserVote = undefined;
                  } else if (c.userVote === 'dislike') {
                    newDislikes--;
                    newLikes++;
                    newUserVote = 'like';
                  } else {
                    newLikes++;
                    newUserVote = 'like';
                  }
                } else {
                  if (c.userVote === 'dislike') {
                    newDislikes--;
                    newUserVote = undefined;
                  } else if (c.userVote === 'like') {
                    newLikes--;
                    newDislikes++;
                    newUserVote = 'dislike';
                  } else {
                    newDislikes++;
                    newUserVote = 'dislike';
                  }
                }

                return {
                  ...c,
                  likes: newLikes,
                  dislikes: newDislikes,
                  userVote: newUserVote
                };
              }
              return c;
            })
          };
        }
        return t;
      })
    }));

    try {
      const { data: existingVote } = await supabase
        .from('comment_votes')
        .select('*')
        .eq('user_id', session.user.id)
        .eq('comment_id', commentId)
        .single();

      if (existingVote) {
        if (existingVote.vote_type === type) {
          await supabase.from('comment_votes').delete().eq('id', existingVote.id);
        } else {
          await supabase.from('comment_votes').update({ vote_type: type }).eq('id', existingVote.id);
        }
      } else {
        await supabase.from('comment_votes').insert({
          user_id: session.user.id,
          comment_id: commentId,
          vote_type: type
        });
      }
    } catch (error) {
      console.error('Error voting comment:', error);
    }
  },

  verifyAIConfig: async () => {
    const { aiSettings } = get();
    if (!aiSettings.apiKey) throw new Error('API Key is missing');
    
    const prompt = "Hello";
    try {
      const result = await callLLM(aiSettings, prompt);
      return true;
    } catch (error: any) {
      throw error;
    }
  },

  fetchModels: async () => {
    const { aiSettings } = get();
    if (!aiSettings.apiKey) return [];

    let baseUrl = aiSettings.baseUrl || (aiSettings.provider === 'openai' ? 'https://api.openai.com/v1' : 'https://api.deepseek.com/v1');
    baseUrl = baseUrl.replace(/\/$/, '');

    try {
      const response = await fetch(`${baseUrl}/models`, {
        headers: {
          'Authorization': `Bearer ${aiSettings.apiKey}`
        }
      });
      if (!response.ok) throw new Error('Failed to fetch models');
      const data = await response.json();
      const models = data.data.map((m: any) => m.id);
      
      set({ aiSettings: { ...aiSettings, availableModels: models } });
      return models;
    } catch (error) {
      console.error('Fetch Models Error:', error);
      return [];
    }
  },

  generateTopicAnalysis: async (topicId) => {
    set({ isAnalyzing: true });
    const { aiSettings, topics } = get();
    const topic = topics.find(t => t.id === topicId);
    if (!topic) {
      set({ isAnalyzing: false });
      return;
    }

    let analysisResult = null;

    if (aiSettings.apiKey) {
      const hasComments = topic.comments.length > 0;
      const commentsText = hasComments 
        ? topic.comments.map(c => `${c.userName} (${c.stance}): ${c.content}`).join('\n')
        : "暂无评论";

      const prompt = `请分析话题“${topic.question}”。
      
      ${hasComments ? `基于以下用户评论进行分析：\n${commentsText}` : '目前暂无用户评论。'}
      
      请返回 JSON 格式，包含以下两个部分：
      1. userAnalysis: ${hasComments ? '基于评论的归纳（summary, agreeReasons, disagreeReasons, overallStrength）' : 'null'}
      2. aiPerspective: 你作为 AI 的辩证视角（summary, points 数组）
      
      JSON 结构示例：
      {
        "userAnalysis": ${hasComments ? '{ "summary": "...", "agreeReasons": [], "disagreeReasons": [], "overallStrength": "..." }' : 'null'},
        "aiPerspective": { "summary": "...", "points": [] }
      }`;
      
      try {
        const result = await callLLM(aiSettings, prompt);
        if (result) {
          const jsonStr = result.replace(/```json\n?|\n?```/g, '');
          const parsed = JSON.parse(jsonStr);
          
          // Sanitize points to ensure they are strings
          if (parsed.aiPerspective && Array.isArray(parsed.aiPerspective.points)) {
            parsed.aiPerspective.points = parsed.aiPerspective.points.map((p: any) => {
              if (typeof p === 'string') return p;
              if (typeof p === 'object' && p !== null) {
                return p.content || p.title || JSON.stringify(p);
              }
              return String(p);
            });
          }
          
          analysisResult = parsed;
        }
      } catch (e) {
        console.error('Failed to generate analysis', e);
      }
    }

    // Fallback mock data
    if (!analysisResult) {
      // Simulate delay for mock data to show loading effect
      if (!aiSettings.apiKey) {
        await new Promise(resolve => setTimeout(resolve, 1500));
      }
      
      analysisResult = {
        userAnalysis: topic.comments.length > 0 ? {
          summary: '该话题引发了激烈的讨论，主要集中在伦理道德与经济效益的权衡上。',
          agreeReasons: ['保障基本人权', '应对自动化失业', '促进社会公平'],
          disagreeReasons: ['降低工作积极性', '财政负担过重', '可能导致通货膨胀'],
          overallStrength: '双方论据均较为充分，但反对派在经济数据引用上略占优势。'
        } : null,
        aiPerspective: {
          summary: '从辩证角度看，该问题涉及社会契约与经济效率的平衡。',
          points: [
            '短期内可能增加财政压力，但长期有助于社会稳定。',
            '需要考虑不同文化背景下的实施难度。',
            '技术进步可能迫使我们重新定义“工作”的价值。'
          ]
        }
      };
    }

    set((state) => ({
      isAnalyzing: false,
      topics: state.topics.map(t => {
        if (t.id === topicId) {
          return {
            ...t,
            topicAnalysis: analysisResult
          };
        }
        return t;
      })
    }));
  },

  generateCommentAnalysis: async (topicId, commentId) => {
    const { aiSettings, topics } = get();
    const topic = topics.find(t => t.id === topicId);
    const comment = topic?.comments.find(c => c.id === commentId);
    if (!topic || !comment) return;

    let analysisResult = null;

    if (aiSettings.apiKey) {
      const prompt = `请分析以下评论的论证质量：
      话题：${topic.question}
      评论：${comment.content}
      
      请返回 JSON 格式，包含以下字段：
      - argument: 核心论点
      - evidence: 论据
      - method: 论证方式
      - strength: 论证强度 (high/medium/low)
      `;
      
      const result = await callLLM(aiSettings, prompt);
      if (result) {
        try {
          const jsonStr = result.replace(/```json\n?|\n?```/g, '');
          analysisResult = JSON.parse(jsonStr);
        } catch (e) {
          console.error('Failed to parse LLM response', e);
        }
      }
    }

    // Fallback mock data
    if (!analysisResult) {
      analysisResult = {
        argument: '用户观点',
        evidence: '个人经历',
        method: '轶事证据',
        strength: 'low'
      };
    }

    set((state) => ({
      topics: state.topics.map(t => {
        if (t.id === topicId) {
          return {
            ...t,
            comments: t.comments.map(c => {
              if (c.id === commentId) {
                return { ...c, analysis: analysisResult };
              }
              return c;
            })
          };
        }
        return t;
      })
    }));
  }
}));
