import React from 'react';
import { AnimatePresence } from 'framer-motion';
import { useAppStore } from '../store/useAppStore';
import { SwipeCard } from '../components/SwipeCard';
import { Header } from '../components/Header';
import { CreateTopicModal } from '../components/CreateTopicModal';
import { VoteType } from '../types';
import { useNavigate } from 'react-router-dom';

export const Home: React.FC = () => {
  const { topics, currentTopicIndex, swipeTopic, activeCategory, searchQuery } = useAppStore();
  const navigate = useNavigate();

  const filteredTopics = topics.filter(t => {
    const matchesCategory = activeCategory === '全部' || t.category === activeCategory;
    const matchesSearch = !searchQuery || 
      t.question.toLowerCase().includes(searchQuery.toLowerCase()) ||
      t.context.toLowerCase().includes(searchQuery.toLowerCase());
    return matchesCategory && matchesSearch;
  });

  const currentTopic = filteredTopics[currentTopicIndex];

  const handleVote = (vote: VoteType, reason?: string) => {
    if (currentTopic) {
      swipeTopic(currentTopic.id, vote, reason);
      // If reason provided, navigate to detail
      if (reason) {
        navigate(`/topic/${currentTopic.id}`);
      }
    }
  };

  const handleSkip = () => {
    if (currentTopic) {
      // Just navigate to detail without voting
      navigate(`/topic/${currentTopic.id}`);
    }
  };

  return (
    <div className="min-h-screen bg-gray-50 flex flex-col">
      <Header />
      <CreateTopicModal />
      
      <main className="flex-1 flex flex-col items-center justify-center p-4 pt-20 overflow-hidden relative">
        <div className="w-full max-w-sm h-[60vh] relative">
          <AnimatePresence>
            {currentTopic ? (
              <SwipeCard
                key={currentTopic.id}
                topic={currentTopic}
                onVote={handleVote}
                onSkip={handleSkip}
              />
            ) : (
              <div className="absolute inset-0 flex items-center justify-center text-center p-8 bg-white rounded-3xl shadow-sm border border-gray-100">
                <div>
                  <h3 className="text-xl font-bold text-gray-900 mb-2">没有更多话题了！</h3>
                  <p className="text-gray-500">
                    在“{activeCategory}”分类下暂时没有更多话题。<br/>
                    稍后再来看看，或者点击右上角“+”创建你自己的话题。
                  </p>
                </div>
              </div>
            )}
          </AnimatePresence>
        </div>

        {/* Instructions */}
        <div className="mt-8 text-center text-gray-400 text-xs space-y-1">
          <p>← 左滑反对 • 右滑赞同 →</p>
          <p>↑ 上滑跳过/中立</p>
          <p>↘ 拖拽直接评论</p>
        </div>
      </main>
    </div>
  );
};
